import { Layout, Button } from "march/ui"

// yönetim paneli: gezinme açılıp kapanır, yan alan isteğe bağlı; çerçeve framed ile her zaman çizilir
export function Dashboard() {
  let $nav = true
  let $aside = false
  return <div sx={{ flex: "col", gap: 2 }}>
    <div sx={{ flex: "row", gap: 2 }}>
      <Button size="sm" on:click={() => $nav = !$nav}>{$nav ? "Gezinmeyi gizle" : "Gezinmeyi göster"}</Button>
      <Button size="sm" on:click={() => $aside = !$aside}>{$aside ? "Yan alanı kapat" : "Yan alanı aç"}</Button>
    </div>
    {() => <Layout features={[]} framed
      header={<div class="sc-ld-box">Panel</div>}
      nav={$nav ? <div class="sc-ld-box">Özet · Raporlar · Ayarlar</div> : undefined}
      aside={$aside ? <div class="sc-ld-box">Bildirimler</div> : undefined}>
      <div class="sc-ld-box sc-ld-main">Bu ayın satışları: 1.240</div>
    </Layout>}
  </div>
}

import { Layout } from "march/ui"

// Layout'un bölgeleri ve seçenekleri: top, header, nav, aside, footer, corners, features, framed, mainId, labels,
// class ve içerik
const Box = (props: { children?: unknown }) => <div class="sc-ld-box">{props.children}</div>

export function LayoutLab() {
  return <Layout class="lab-layout" features={[]} framed mainId="lab-main" labels={{ skip: "İçeriğe atla" }}
    top={<Box>Duyuru</Box>} header={<Box>Üst bilgi</Box>} nav={<Box>Gezinme</Box>} aside={<Box>Yan alan</Box>} footer={<Box>Alt bilgi</Box>}>
    <Box>Ana içerik</Box>
  </Layout>
}

import { test, expect, renderTest } from "march/testing"
import { LayoutLab } from "./LayoutLab.tsx"

// LayoutLab'in testleri: kaydedince Testler sekmesinde çalışır
test("bütün bölgeler çizilir", () => {
  const s = renderTest(() => <LayoutLab />)
  for (const t of ["Duyuru", "Üst bilgi", "Gezinme", "Yan alan", "Alt bilgi", "Ana içerik"]) expect(s.sees(t)).toBe(true)
})

test("ana bölgenin kimliği mainId", () => {
  const s = renderTest(() => <LayoutLab />)
  expect(s.get("#lab-main")).not.toBe(null)
})

test("class köke eklenir", () => {
  const s = renderTest(() => <LayoutLab />)
  expect(s.get(".lab-layout")).not.toBe(null)
})
